namespace DonationHub.Domain.Campaigns;

public enum CampaignStatus { Active, Completed, Expired }

public sealed class Campaign : Entity, ISoftDeletable
{
    private Campaign() { }                       // EF Core
    private Campaign(Guid id) : base(id) { }

    public string TitleAr { get; private set; } = default!;
    public string TitleEn { get; private set; } = default!;
    public string DescriptionAr { get; private set; } = default!;
    public string DescriptionEn { get; private set; } = default!;
    public decimal GoalAmount { get; private set; }
    public decimal RaisedAmount { get; private set; }
    public DateTime EndDate { get; private set; }
    public Guid CategoryId { get; private set; }
    public string? BannerFileName { get; private set; }
    public CampaignStatus Status { get; private set; }
    public Guid CreatedByUserId { get; private set; }
    public DateTime CreatedAt { get; private set; }
    public DateTime UpdatedAt { get; private set; }
    public byte[] RowVersion { get; private set; } = [];

    // يضبطها الـ SoftDeleteInterceptor فقط (الواجهة تفرض set عامًا)
    // القاعدة 9: ISoftDeletable + الـ interceptor يحوّلان كل حذف للحملة إلى حذف ناعم، فالحذف النهائي مستحيل بالتصميم
    public bool IsDeleted { get; set; }
    public DateTime? DeletedAtUtc { get; set; }

    public bool IsFinal => Status is CampaignStatus.Completed or CampaignStatus.Expired;

    public static Campaign Create(
        string titleAr, string titleEn, string descriptionAr, string descriptionEn,
        decimal goalAmount, DateTime endDate, Guid categoryId, Guid createdByUserId, DateTime utcNow)
    {
        EnsureGoalIsPositive(goalAmount);          // القاعدة 1
        EnsureEndDateInFuture(endDate, utcNow);    // القاعدة 2

        return new Campaign(Guid.NewGuid())
        {
            TitleAr = titleAr.Trim(),
            TitleEn = titleEn.Trim(),
            DescriptionAr = descriptionAr.Trim(),
            DescriptionEn = descriptionEn.Trim(),
            GoalAmount = goalAmount,
            RaisedAmount = 0,
            EndDate = endDate,
            CategoryId = categoryId,
            CreatedByUserId = createdByUserId,
            Status = CampaignStatus.Active,
            CreatedAt = utcNow,
            UpdatedAt = utcNow
        };
    }

    public void Update(
        string titleAr, string titleEn, string descriptionAr, string descriptionEn,
        decimal goalAmount, DateTime endDate, Guid categoryId, DateTime utcNow)
    {
        if (IsFinal)                                // القاعدة 8
            throw new DomainException("Campaign.NotActive", "A completed or expired campaign cannot be changed.");

        EnsureGoalIsPositive(goalAmount);
        if (goalAmount < RaisedAmount)              // القاعدة 7
            throw new DomainException("Campaign.GoalBelowRaised", "Goal amount cannot be lower than the raised amount.");
        if (endDate != EndDate)                     // القاعدة 2 عند تغيير التاريخ فقط
            EnsureEndDateInFuture(endDate, utcNow);

        TitleAr = titleAr.Trim();
        TitleEn = titleEn.Trim();
        DescriptionAr = descriptionAr.Trim();
        DescriptionEn = descriptionEn.Trim();
        GoalAmount = goalAmount;
        EndDate = endDate;
        CategoryId = categoryId;
        UpdatedAt = utcNow;
    }

    public void EnsureCanAcceptDonation(DateTime utcNow)   // القاعدة 3
    {
        if (Status != CampaignStatus.Active || EndDate <= utcNow)
            throw new DomainException("Campaign.NotActive", "The campaign is not accepting donations.");
    }

    // internal: لا يستدعيها إلا Donation.MarkSucceeded داخل نفس الـ assembly ← القاعدة 5
    internal void ApplySucceededDonation(decimal amount, DateTime utcNow)
    {
        // دفعة متأخرة على حملة منتهية تُقبل (المتبرع دُفع منه بالفعل) لكن الحالة لا تتغيّر
        RaisedAmount += amount;
        if (Status == CampaignStatus.Active && RaisedAmount >= GoalAmount)
            Status = CampaignStatus.Completed;      // القاعدة 6
        UpdatedAt = utcNow;
    }

    public void MarkExpiredIfDue(DateTime utcNow)
    {
        if (Status == CampaignStatus.Active && EndDate <= utcNow)
        {
            Status = CampaignStatus.Expired;
            UpdatedAt = utcNow;
        }
    }

    private static void EnsureGoalIsPositive(decimal goalAmount)
    {
        if (goalAmount <= 0)
            throw new DomainException("Validation.Failed", "Goal amount must be greater than zero.");
    }

    private static void EnsureEndDateInFuture(DateTime endDate, DateTime utcNow)
    {
        if (endDate <= utcNow)
            throw new DomainException("Campaign.EndDateInPast", "End date must be in the future.");
    }
}

