public enum DonationStatus { Pending, Succeeded, Failed }

public sealed class Donation : Entity
{
    private Donation() { }
    private Donation(Guid id) : base(id) { }

    public Guid CampaignId { get; private set; }
    public Guid DonorUserId { get; private set; }
    public decimal Amount { get; private set; }
    public DonationStatus Status { get; private set; }
    public DateTime CreatedAt { get; private set; }
    public DateTime? CompletedAt { get; private set; }
    public string? FailureReason { get; private set; }
    public string? ReceiptNumber { get; private set; }
    public string? ReceiptFileName { get; private set; }

    public static Donation Create(Campaign campaign, Guid donorUserId, decimal amount,
        decimal minAmount, decimal maxAmount, DateTime utcNow)
    {
        campaign.EnsureCanAcceptDonation(utcNow);                 // القاعدة 3
        if (amount < minAmount || amount > maxAmount)             // القاعدة 4
            throw new DomainException("Donation.AmountOutOfRange",
                $"Amount must be between {minAmount} and {maxAmount}.");

        return new Donation(Guid.NewGuid())
        {
            CampaignId = campaign.Id,
            DonorUserId = donorUserId,
            Amount = amount,
            Status = DonationStatus.Pending,
            CreatedAt = utcNow
        };
    }

    public void MarkSucceeded(Campaign campaign, string receiptNumber, DateTime utcNow)
    {
        EnsurePending();                                          // القاعدة 8
        if (campaign.Id != CampaignId)
            throw new DomainException("Donation.InvalidState", "Donation does not belong to this campaign.");

        Status = DonationStatus.Succeeded;
        CompletedAt = utcNow;
        ReceiptNumber = receiptNumber;
        campaign.ApplySucceededDonation(Amount, utcNow);          // القاعدتان 5 و 6
    }

    public void MarkFailed(string reason, DateTime utcNow)
    {
        EnsurePending();
        Status = DonationStatus.Failed;
        FailureReason = reason;
        CompletedAt = utcNow;
    }

    private void EnsurePending()
    {
        if (Status != DonationStatus.Pending)
            throw new DomainException("Donation.InvalidState", "Donation is already in a final state.");
    }
}

