namespace DonationHub.Domain.Categories;

public sealed class Category : Entity
{
    public const int NameMaxLength = 100;

    private Category() { }
    private Category(Guid id) : base(id) { }

    public string NameAr { get; private set; } = default!;
    public string NameEn { get; private set; } = default!;
    public string? DescriptionAr { get; private set; }
    public string? DescriptionEn { get; private set; }
    public DateTime CreatedAt { get; private set; }
    public DateTime UpdatedAt { get; private set; }

    public static Category Create(string nameAr, string nameEn, string? descriptionAr, string? descriptionEn, DateTime utcNow) =>
        new(Guid.NewGuid())
        {
            NameAr = RequireName(nameAr, nameof(NameAr)),
            NameEn = RequireName(nameEn, nameof(NameEn)),
            DescriptionAr = Normalize(descriptionAr),
            DescriptionEn = Normalize(descriptionEn),
            CreatedAt = utcNow,
            UpdatedAt = utcNow
        };

    public void Update(string nameAr, string nameEn, string? descriptionAr, string? descriptionEn, DateTime utcNow)
    {
        NameAr = RequireName(nameAr, nameof(NameAr));
        NameEn = RequireName(nameEn, nameof(NameEn));
        DescriptionAr = Normalize(descriptionAr);
        DescriptionEn = Normalize(descriptionEn);
        UpdatedAt = utcNow;
    }

    // القاعدة 10: الكيان لا يستعلم من قاعدة البيانات؛ الـ handler يجلب الحقيقة ويمرّرها، والقرار هنا
    public void EnsureCanBeDeleted(bool hasCampaigns)
    {
        if (hasCampaigns)
            throw new DomainException("Category.HasCampaigns", "Cannot delete a category that has campaigns.");
    }

    private static string RequireName(string? value, string field)
    {
        var name = value?.Trim();
        if (string.IsNullOrEmpty(name))
            throw new DomainException("Validation.Failed", $"{field} is required.");
        if (name.Length > NameMaxLength)
            throw new DomainException("Validation.Failed", $"{field} must be at most {NameMaxLength} characters.");
        return name;
    }

    private static string? Normalize(string? value) => string.IsNullOrWhiteSpace(value) ? null : value.Trim();
}

