namespace DonationHub.Domain.Identity;

public sealed class RefreshToken : Entity
{
    private RefreshToken() { }
    private RefreshToken(Guid id) : base(id) { }

    public Guid UserId { get; private set; }
    public string TokenHash { get; private set; } = default!;
    public DateTime CreatedAt { get; private set; }
    public DateTime ExpiresAt { get; private set; }
    public DateTime? RevokedAt { get; private set; }
    public Guid? ReplacedByTokenId { get; private set; }

    public static RefreshToken Issue(Guid userId, string tokenHash, DateTime utcNow, TimeSpan lifetime) =>
        new(Guid.NewGuid())
        {
            UserId = userId,
            TokenHash = tokenHash,
            CreatedAt = utcNow,
            ExpiresAt = utcNow.Add(lifetime)
        };

    public bool IsActive(DateTime utcNow) => RevokedAt is null && ExpiresAt > utcNow;

    public void Revoke(DateTime utcNow, Guid? replacedByTokenId = null)
    {
        if (RevokedAt is not null) return;      // الإلغاء مرة واحدة فقط
        RevokedAt = utcNow;
        ReplacedByTokenId = replacedByTokenId;
    }
}

