public sealed class CampaignConfiguration : IEntityTypeConfiguration<Campaign>
{
    public void Configure(EntityTypeBuilder<Campaign> builder)
    {
        builder.ToTable("Campaigns");
        builder.HasKey(c => c.Id);

        builder.Property(c => c.TitleAr).HasMaxLength(200).IsRequired();
        builder.Property(c => c.TitleEn).HasMaxLength(200).IsRequired();
        builder.Property(c => c.DescriptionAr).HasMaxLength(4000).IsRequired();
        builder.Property(c => c.DescriptionEn).HasMaxLength(4000).IsRequired();
        builder.Property(c => c.GoalAmount).HasPrecision(18, 2);
        builder.Property(c => c.RaisedAmount).HasPrecision(18, 2);
        builder.Property(c => c.BannerFileName).HasMaxLength(260);
        builder.Property(c => c.Status).HasConversion<string>().HasMaxLength(20);
        builder.Property(c => c.RowVersion).IsRowVersion();            // concurrency token

        builder.HasOne<Category>()
            .WithMany()
            .HasForeignKey(c => c.CategoryId)
            .OnDelete(DeleteBehavior.Restrict);                          // القاعدة 10 على مستوى DB

        builder.HasOne<ApplicationUser>()
            .WithMany()
            .HasForeignKey(c => c.CreatedByUserId)
            .OnDelete(DeleteBehavior.Restrict);

        builder.HasIndex(c => new { c.Status, c.EndDate });           // للقوائم العامة والـ job الدوري لاحقًا
        builder.HasQueryFilter(c => !c.IsDeleted);
    }
}

