namespace DonationHub.Infrastructure.Persistence.Repositories;

internal sealed class GenericRepository<T>(AppDbContext db) : IGenericRepository<T> where T : Entity
{
    private readonly DbSet<T> _set = db.Set<T>();

    public Task<T?> GetByIdAsync(Guid id, CancellationToken ct = default) =>
        _set.FirstOrDefaultAsync(e => e.Id == id, ct);

    public async Task AddAsync(T entity, CancellationToken ct = default) =>
        await _set.AddAsync(entity, ct);

    public void Remove(T entity) => _set.Remove(entity);   // يتحوّل لحذف ناعم إن كان ISoftDeletable

    public Task<bool> AnyAsync(Expression<Func<T, bool>> predicate, CancellationToken ct = default) =>
        _set.AnyAsync(predicate, ct);
}

internal sealed class UnitOfWork(AppDbContext db) : IUnitOfWork
{
    private readonly Dictionary<Type, object> _repositories = [];

    public IGenericRepository<T> Repository<T>() where T : Entity
    {
        if (!_repositories.TryGetValue(typeof(T), out var repository))
        {
            repository = new GenericRepository<T>(db);
            _repositories[typeof(T)] = repository;
        }
        return (IGenericRepository<T>)repository;
    }

    public Task<int> SaveChangesAsync(CancellationToken ct = default) => db.SaveChangesAsync(ct);
}

internal sealed class ReadDbContext(AppDbContext db) : IReadDbContext
{
    public IQueryable<Category> Categories => db.Categories.AsNoTracking();
    public IQueryable<Campaign> Campaigns => db.Campaigns.AsNoTracking();
    public IQueryable<Campaign> CampaignsIncludingDeleted => db.Campaigns.IgnoreQueryFilters().AsNoTracking();
}

