internal sealed class AuthService(
    UserManager<ApplicationUser> userManager,
    AppDbContext db,
    JwtTokenService tokenService,
    IOptions<JwtOptions> jwtOptions,
    TimeProvider timeProvider) : IAuthService
{
    private readonly JwtOptions _jwt = jwtOptions.Value;

    public async Task<CurrentUserResponse> RegisterAsync(RegisterRequest request, CancellationToken ct)
    {
        var language = string.IsNullOrWhiteSpace(request.PreferredLanguage) ? "en" : request.PreferredLanguage;
        if (language is not ("en" or "ar"))
            throw new AppException("Validation.Failed", 400, "PreferredLanguage must be 'en' or 'ar'.");

        if (await userManager.FindByEmailAsync(request.Email) is not null)   // بدون حساسية لحالة الأحرف
            throw AuthErrors.EmailAlreadyExists();

        var user = new ApplicationUser
        {
            Id = Guid.NewGuid(),
            UserName = request.Email,
            Email = request.Email,
            FullName = request.FullName.Trim(),
            PreferredLanguage = language,
            IsActive = true,
            CreatedAt = timeProvider.GetUtcNow().UtcDateTime
        };

        var result = await userManager.CreateAsync(user, request.Password);   // يطبّق سياسة IDN-02
        if (!result.Succeeded)
            throw new AppException("Validation.Failed", 400, string.Join(" ", result.Errors.Select(e => e.Description)));

        var roleResult = await userManager.AddToRoleAsync(user, Roles.Donor);   // لا نتجاهل النتيجة
        if (!roleResult.Succeeded)
            throw new InvalidOperationException("Assigning the Donor role failed. Were the roles seeded?");

        return ToResponse(user, [Roles.Donor]);
    }

    public async Task<AuthResponse> LoginAsync(LoginRequest request, CancellationToken ct)
    {
        var user = await userManager.FindByEmailAsync(request.Email);
        if (user is null || !await userManager.CheckPasswordAsync(user, request.Password))
            throw AuthErrors.InvalidCredentials();      // IDN-12: نفس الخطأ للحالتين

        if (!user.IsActive)
            throw AuthErrors.AccountDeactivated();      // IDN-10

        return await IssueTokensAsync(user, replacing: null, ct);
    }

    public async Task<AuthResponse> RefreshAsync(string refreshToken, CancellationToken ct)
    {
        var now = timeProvider.GetUtcNow().UtcDateTime;
        var hash = RefreshTokenGenerator.Hash(refreshToken);
        var stored = await db.RefreshTokens.SingleOrDefaultAsync(t => t.TokenHash == hash, ct);

        if (stored is null || !stored.IsActive(now))
            throw AuthErrors.RefreshTokenInvalid();     // غير موجود أو منتهٍ أو ملغى

        var user = await userManager.FindByIdAsync(stored.UserId.ToString())
                   ?? throw AuthErrors.RefreshTokenInvalid();
        if (!user.IsActive)
            throw AuthErrors.AccountDeactivated();

        return await IssueTokensAsync(user, replacing: stored, ct);   // IDN-06: تدوير
    }

    public async Task LogoutAsync(Guid userId, string refreshToken, CancellationToken ct)
    {
        var hash = RefreshTokenGenerator.Hash(refreshToken);
        var stored = await db.RefreshTokens.SingleOrDefaultAsync(t => t.TokenHash == hash && t.UserId == userId, ct);
        if (stored is null) return;                     // لا نكشف شيئًا؛ الخروج دائمًا 204

        stored.Revoke(timeProvider.GetUtcNow().UtcDateTime);
        await db.SaveChangesAsync(ct);
    }

    private async Task<AuthResponse> IssueTokensAsync(ApplicationUser user, RefreshToken? replacing, CancellationToken ct)
    {
        var now = timeProvider.GetUtcNow().UtcDateTime;
        var rawRefreshToken = RefreshTokenGenerator.Generate();
        var newToken = RefreshToken.Issue(user.Id, RefreshTokenGenerator.Hash(rawRefreshToken), now,
            TimeSpan.FromDays(_jwt.RefreshTokenExpiryDays));

        replacing?.Revoke(now, newToken.Id);            // القديم يُلغى ويُربط بالجديد
        db.RefreshTokens.Add(newToken);
        try
        {
            await db.SaveChangesAsync(ct);              // الإلغاء والإضافة في نفس الـ SaveChanges
        }
        catch (DbUpdateConcurrencyException) when (replacing is not null)
        {
            throw AuthErrors.RefreshTokenInvalid();     // طلب متزامن استخدم نفس الرمز قبلنا (RevokedAt concurrency token)
        }

        var roles = await userManager.GetRolesAsync(user);
        var (accessToken, expiresAt) = tokenService.CreateAccessToken(user, roles);
        return new AuthResponse(accessToken, expiresAt, rawRefreshToken);   // الخام يُرسل للعميل مرة واحدة فقط
    }

    public async Task<CurrentUserResponse> GetCurrentUserAsync(Guid userId, CancellationToken ct)   // IDN-09
    {
        var user = await userManager.FindByIdAsync(userId.ToString())
                   ?? throw AuthErrors.InvalidCredentials();   // توكن صالح لمستخدم غير موجود
        return ToResponse(user, await userManager.GetRolesAsync(user));
    }

    public async Task<CurrentUserResponse> CreateStaffAsync(CreateStaffRequest request, CancellationToken ct)   // IDN-08
    {
        if (request.Role is not (Roles.Admin or Roles.CampaignManager))   // لا يُنشأ Donor من هنا
            throw new AppException("Validation.Failed", 400, "Role must be Admin or CampaignManager.");
        if (await userManager.FindByEmailAsync(request.Email) is not null)
            throw AuthErrors.EmailAlreadyExists();

        var user = new ApplicationUser
        {
            Id = Guid.NewGuid(), UserName = request.Email, Email = request.Email,
            FullName = request.FullName.Trim(), IsActive = true,
            CreatedAt = timeProvider.GetUtcNow().UtcDateTime
        };

        var result = await userManager.CreateAsync(user, request.TemporaryPassword);   // نفس سياسة IDN-02
        if (!result.Succeeded)
            throw new AppException("Validation.Failed", 400, string.Join(" ", result.Errors.Select(e => e.Description)));

        var roleResult = await userManager.AddToRoleAsync(user, request.Role);
        if (!roleResult.Succeeded)
            throw new InvalidOperationException($"Assigning the {request.Role} role failed.");

        return ToResponse(user, [request.Role]);
    }

    private static CurrentUserResponse ToResponse(ApplicationUser user, IEnumerable<string> roles) =>
        new(user.Id, user.Email!, user.FullName, user.PreferredLanguage, [.. roles]);
}

