internal sealed class AppExceptionHandler(IProblemDetailsService problemDetailsService, ILogger<AppExceptionHandler> logger)
    : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(HttpContext httpContext, Exception exception, CancellationToken ct)
    {
        var (status, code, title) = exception switch
        {
            AppException app => (app.StatusCode, app.Code, app.Message),
            DomainException domain when domain.Code == "Validation.Failed" => (StatusCodes.Status400BadRequest, domain.Code, domain.Message),
            DomainException domain when domain.Code is "Campaign.NotActive" or "Donation.InvalidState" or "Category.HasCampaigns"
                => (StatusCodes.Status409Conflict, domain.Code, domain.Message),            // حسب كتالوج SRS §6.1
            DomainException domain => (StatusCodes.Status422UnprocessableEntity, domain.Code, domain.Message),
            _ => (StatusCodes.Status500InternalServerError, "Server.Error", "An unexpected error occurred.")
        };

        if (status == StatusCodes.Status500InternalServerError)
            logger.LogError(exception, "Unhandled exception");   // التفاصيل في الـ log فقط، لا للعميل

        var problem = new ProblemDetails { Status = status, Title = title };
        problem.Extensions["code"] = code;
        problem.Extensions["traceId"] = httpContext.TraceIdentifier;

        httpContext.Response.StatusCode = status;
        return await problemDetailsService.TryWriteAsync(new ProblemDetailsContext
        {
            HttpContext = httpContext,
            Exception = exception,
            ProblemDetails = problem
        });
    }
}

public static class DbSeeder
{
    public static async Task SeedAsync(IServiceProvider services, bool isDevelopment)
    {
        using var scope = services.CreateScope();
        var sp = scope.ServiceProvider;
        var roleManager = sp.GetRequiredService<RoleManager<IdentityRole<Guid>>>();
        var userManager = sp.GetRequiredService<UserManager<ApplicationUser>>();
        var admin = sp.GetRequiredService<IOptions<SeedAdminOptions>>().Value;
        var db = sp.GetRequiredService<AppDbContext>();
        var now = sp.GetRequiredService<TimeProvider>().GetUtcNow().UtcDateTime;

        foreach (var role in new[] { Roles.Admin, Roles.CampaignManager, Roles.Donor })
        {
            if (!await roleManager.RoleExistsAsync(role)
                && !(await roleManager.CreateAsync(new IdentityRole<Guid>(role))).Succeeded)
                throw new InvalidOperationException($"Seeding role {role} failed.");
        }

        await EnsureUserAsync(userManager, admin.Email, admin.Password, admin.FullName, Roles.Admin, now);  // IDN-11

        if (!isDevelopment) return;

        // مستخدما التجربة: بياناتهما من user-secrets عبر DevSeedUsersOptions (لا تُكتب في الكود)
        // await EnsureUserAsync(userManager, dev.ManagerEmail, dev.ManagerPassword, "Test Manager", Roles.CampaignManager, now);
        // await EnsureUserAsync(userManager, dev.DonorEmail, dev.DonorPassword, "Test Donor", Roles.Donor, now);

        if (!await db.Categories.AnyAsync())
        {
            db.Categories.AddRange(
                Category.Create("صحة", "Health", null, null, now),
                Category.Create("تعليم", "Education", null, null, now),
                Category.Create("إغاثة", "Relief", null, null, now),
                Category.Create("أيتام", "Orphans", null, null, now),
                Category.Create("بيئة", "Environment", null, null, now));
            await db.SaveChangesAsync();
        }
    }

    private static async Task EnsureUserAsync(UserManager<ApplicationUser> userManager,
        string email, string password, string fullName, string role, DateTime now)
    {
        if (await userManager.FindByEmailAsync(email) is not null) return;

        var user = new ApplicationUser
        {
            Id = Guid.NewGuid(), UserName = email, Email = email, EmailConfirmed = true,
            FullName = fullName, IsActive = true, CreatedAt = now
        };
        var result = await userManager.CreateAsync(user, password);
        if (!result.Succeeded)
            throw new InvalidOperationException(
                $"Seeding {email} failed: {string.Join(", ", result.Errors.Select(e => e.Description))}");

        var roleResult = await userManager.AddToRoleAsync(user, role);
        if (!roleResult.Succeeded)
            throw new InvalidOperationException($"Assigning {role} to {email} failed.");
    }
}

