public sealed record CategoryResponse(Guid Id, string NameAr, string NameEn, string? DescriptionAr, string? DescriptionEn);
public sealed record UpsertCategoryRequest(string NameAr, string NameEn, string? DescriptionAr, string? DescriptionEn);

public static class CategoryErrors
{
    public static AppException NotFound() => new("Category.NotFound", 404, "Category was not found.");
    public static AppException DuplicateName() => new("Validation.Failed", 400, "A category with the same Arabic or English name already exists.");
}

public sealed class GetCategoriesHandler(IReadDbContext read)
{
    public async Task<IReadOnlyList<CategoryResponse>> HandleAsync(CancellationToken ct) =>
        await read.Categories
            .OrderBy(c => c.NameEn)
            .Select(c => new CategoryResponse(c.Id, c.NameAr, c.NameEn, c.DescriptionAr, c.DescriptionEn))
            .ToListAsync(ct);
}

public sealed class GetCategoryByIdHandler(IReadDbContext read)
{
    public async Task<CategoryResponse> HandleAsync(Guid id, CancellationToken ct) =>
        await read.Categories
            .Where(c => c.Id == id)
            .Select(c => new CategoryResponse(c.Id, c.NameAr, c.NameEn, c.DescriptionAr, c.DescriptionEn))
            .FirstOrDefaultAsync(ct)
        ?? throw CategoryErrors.NotFound();               // CAT-04: 404
}

public sealed class CreateCategoryHandler(IUnitOfWork uow, IReadDbContext read, TimeProvider timeProvider)
{
    public async Task<CategoryResponse> HandleAsync(UpsertCategoryRequest request, CancellationToken ct)
    {
        var category = Category.Create(request.NameAr, request.NameEn,
            request.DescriptionAr, request.DescriptionEn, timeProvider.GetUtcNow().UtcDateTime);

        // فحص مسبق برسالة واضحة؛ والـ unique index يحمي من التزامن
        if (await read.Categories.AnyAsync(c => c.NameAr == category.NameAr || c.NameEn == category.NameEn, ct))
            throw CategoryErrors.DuplicateName();

        await uow.Repository<Category>().AddAsync(category, ct);
        await uow.SaveChangesAsync(ct);
        return new CategoryResponse(category.Id, category.NameAr, category.NameEn, category.DescriptionAr, category.DescriptionEn);
    }
}

public sealed class UpdateCategoryHandler(IUnitOfWork uow, IReadDbContext read, TimeProvider timeProvider)
{
    public async Task<CategoryResponse> HandleAsync(Guid id, UpsertCategoryRequest request, CancellationToken ct)
    {
        var category = await uow.Repository<Category>().GetByIdAsync(id, ct) ?? throw CategoryErrors.NotFound();
        category.Update(request.NameAr, request.NameEn,
            request.DescriptionAr, request.DescriptionEn, timeProvider.GetUtcNow().UtcDateTime);

        // التفرد يُفحص مع استثناء التصنيف نفسه، وإلا يفشل تعديل الوصف وحده
        if (await read.Categories.AnyAsync(c => c.Id != id && (c.NameAr == category.NameAr || c.NameEn == category.NameEn), ct))
            throw CategoryErrors.DuplicateName();

        await uow.SaveChangesAsync(ct);                   // الكيان متتبَّع؛ لا حاجة لـ Update
        return new CategoryResponse(category.Id, category.NameAr, category.NameEn, category.DescriptionAr, category.DescriptionEn);
    }
}

public sealed class DeleteCategoryHandler(IUnitOfWork uow, IReadDbContext read)
{
    public async Task HandleAsync(Guid id, CancellationToken ct)
    {
        var categories = uow.Repository<Category>();
        var category = await categories.GetByIdAsync(id, ct) ?? throw CategoryErrors.NotFound();

        // IgnoreQueryFilters: الحملات المحذوفة ناعمًا ما زالت صفوفًا تمنع الحذف بسبب FK Restrict
        var hasCampaigns = await read.CampaignsIncludingDeleted.AnyAsync(c => c.CategoryId == id, ct);
        category.EnsureCanBeDeleted(hasCampaigns);        // CAT-04 / القاعدة 10: القرار في الـ Domain (409)

        categories.Remove(category);
        await uow.SaveChangesAsync(ct);
    }
}

